using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System;
using System.Linq;
using System.Collections.Generic;
using FalloutPort;
public static class BuildWeaponLoot {
 static GameObject Box(string name,Transform parent,Vector3 p,Vector3 size,Material material){var o=GameObject.CreatePrimitive(PrimitiveType.Cube);o.name=name;o.transform.SetParent(parent,false);o.transform.localPosition=p;o.transform.localScale=size;o.GetComponent<Renderer>().sharedMaterial=material;return o;}
 public static string Build(){var game=UnityEngine.Object.FindAnyObjectByType<PortGame>();var old=GameObject.Find("World weapon loot");if(old)UnityEngine.Object.DestroyImmediate(old);var root=new GameObject("World weapon loot");var interactions=game.interactions.Where(x=>x&&!x.id.StartsWith("loot:")).ToList();var defs=Resources.LoadAll<PortWeaponDefinition>("WeaponDefinitions").OrderBy(x=>x.id).ToArray();var groups=new List<string>[8];for(int i=0;i<8;i++)groups[i]=new List<string>();string[] loose={"hunting_knife","lead_pipe","pipe_rifle","pistol_32"};foreach(var d in defs){if(loose.Contains(d.id))continue;int group=d.unique?7:d.stats.reloadType=="throw"?6:d.stats.reloadType=="melee"?5:d.stats.projectile=="missile"||d.stats.projectile=="mininuke"||d.id=="minigun"||d.id=="gatling_laser"||d.id=="flamer"?4:d.stats.ammo!=null&&(d.stats.ammo.Contains("cell")||d.stats.ammo=="ammo_ecp")?3:d.id.Contains("shotgun")||d.id=="scrapshot_launcher"||d.id=="stinger_dart_gun"||d.id=="spikedriver"?2:d.oneHanded?0:1;groups[group].Add(d.id);}
 string[] names={"Security sidearm locker","Security rifle locker","Workshop weapons case","Experimental energy case","Heavy equipment reserve","Maintenance tool chest","Demolition supplies","Overseer's confiscated weapons"};var steel=AssetDatabase.LoadAssetAtPath<Material>("Assets/FalloutPort/Expansion/Military steel.mat");var dark=AssetDatabase.LoadAssetAtPath<Material>("Assets/FalloutPort/Expansion/Rubber.mat");var gold=AssetDatabase.LoadAssetAtPath<Material>("Assets/FalloutPort/Expansion/Target paint.mat");
 for(int i=0;i<12;i++){bool single=i>=8;int n=i-8;Vector3[] positions={new Vector3(16,0,10),new Vector3(18,0,24),new Vector3(-14,0,-52),new Vector3(22,0,22),new Vector3(23,0,25),new Vector3(-14,0,-68),new Vector3(18,0,27),new Vector3(24,4.5f,22),new Vector3(-27,0,12),new Vector3(-14,0,-54),new Vector3(-6,0,-8),new Vector3(23,0,8)};Vector3 position=positions[i];var o=new GameObject(single?"Loose "+loose[n]:names[i]);o.transform.SetParent(root.transform);o.transform.position=position;var loot=o.AddComponent<PortWorldLoot>();loot.lootId="vault120_weapon_"+i;loot.title=single?Array.Find(defs,x=>x.id==loose[n]).displayName:names[i];loot.weaponIds=single?new[]{loose[n]}:groups[i].ToArray();loot.loose=single;loot.requiredStage=single?0:i>=3&&i!=5?6:2;Box("Storage base",o.transform,new Vector3(0,.4f,0),new Vector3(.95f,.8f,.65f),steel);Box("Top",o.transform,new Vector3(0,.84f,0),new Vector3(1,.08f,.7f),dark);Box("Latch",o.transform,new Vector3(0,.65f,-.34f),new Vector3(.12f,.18f,.04f),gold);var it=o.AddComponent<PortInteractable>();it.id="loot:"+loot.lootId;it.displayName=loot.title;interactions.Add(it);
 if(single){var model=UnityEngine.Object.Instantiate(Array.Find(defs,x=>x.id==loose[n]).prefab,o.transform);model.name="Collectible weapon";var arms=model.transform.Find("First person arms");if(arms)UnityEngine.Object.DestroyImmediate(arms.gameObject);foreach(var t in model.GetComponentsInChildren<Transform>())t.gameObject.layer=0;model.transform.localPosition=Vector3.zero;model.transform.localRotation=Quaternion.Euler(0,35,90);var renderers=model.GetComponentsInChildren<Renderer>();Bounds b=renderers[0].bounds;foreach(var r in renderers)b.Encapsulate(r.bounds);float factor=Mathf.Min(1,.8f/Mathf.Max(b.size.x,b.size.z));model.transform.localScale=Vector3.one*factor;b=renderers[0].bounds;foreach(var r in renderers)b.Encapsulate(r.bounds);model.transform.position+=o.transform.position+new Vector3(0,.89f,0)-new Vector3(b.center.x,b.min.y,b.center.z);loot.visual=model.transform;}}
 game.interactions=interactions.ToArray();EditorSceneManager.MarkSceneDirty(game.gameObject.scene);EditorSceneManager.SaveScene(game.gameObject.scene);return "Placed 4 visible pickups and 8 categorized loot cases covering "+defs.Length+" weapons";}
}
